using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.InputSystem;

// Menu-only navigation; mouse pointer processing remains owned by InputSystemUIInputModule.
public sealed class TrainingOptionNavigation:MonoBehaviour{
 TrainingOverlay owner;GameObject root;Selectable selected;Dictionary<Selectable,Outline> outlines=new Dictionary<Selectable,Outline>();bool ownsNavigation,previousNavigation,adjusting;float originalValue;
 public bool Adjusting=>adjusting||(selected!=null&&selected.GetComponent<TrainingOptionValue>()?.Editing==true);public string FocusedName=>selected==null?"":selected.name;
 public void Configure(TrainingOverlay overlay,GameObject optionRoot){owner=overlay;root=optionRoot;foreach(var field in root.GetComponentsInChildren<InputField>(true))field.shouldActivateOnSelect=false;}
 bool Eligible(Selectable s)=>s!=null&&s.IsActive()&&s.IsInteractable()&&s.transform.IsChildOf(root.transform)&&(!owner.KeyConfigConfirmVisible||s.transform.IsChildOf(owner.KeyConfigDialogRoot));
 void Update(){if(owner==null||!owner.OptionVisible||EventSystem.current==null||owner.KeyConfigNavigationBlocked)return;
  if(!ownsNavigation){previousNavigation=EventSystem.current.sendNavigationEvents;EventSystem.current.sendNavigationEvents=false;ownsNavigation=true;}
  var current=EventSystem.current.currentSelectedGameObject;var focus=current==null?null:current.GetComponent<Selectable>();if(!Eligible(focus)){var nav=root.transform.Find("Panel/NavTraining");focus=nav==null?null:nav.GetComponent<Selectable>();if(!Eligible(focus))foreach(var item in root.GetComponentsInChildren<Selectable>())if(Eligible(item)){focus=item;break;}if(focus!=null)EventSystem.current.SetSelectedGameObject(focus.gameObject);}
  if(focus!=selected){adjusting=false;ShowSelection(focus);}
  if(selected==null||owner.MenuOpenedThisFrame)return;var menuFrame=owner.MenuInputFrame;bool confirm=menuFrame.confirm,cancel=menuFrame.cancel||menuFrame.option;bool up=menuFrame.direction.y>0,down=menuFrame.direction.y<0,left=menuFrame.direction.x<0,right=menuFrame.direction.x>0;var field=selected as InputField;if(field!=null&&field.isFocused){if(menuFrame.option||menuFrame.cancelFromPad)field.DeactivateInputField();return;}
  var value=selected.GetComponent<TrainingOptionValue>();if(value!=null&&value.Editing){if(cancel)value.Cancel();else if(confirm)value.Commit();else if(up)value.Adjust(10);else if(down)value.Adjust(-10);else if(left)value.Adjust(-1);else if(right)value.Adjust(1);ShowSelection(selected);return;}
  if(adjusting){float step=selected is Slider numberSlider&&numberSlider.wholeNumbers?1f/Mathf.Max(1,numberSlider.maxValue-numberSlider.minValue):.1f;if(cancel){SetValue(originalValue);adjusting=false;ShowSelection(selected);}else if(confirm){adjusting=false;ShowSelection(selected);}else if(left||down)SetValue(Value()-step);else if(right||up)SetValue(Value()+step);return;}
  if(cancel){if(owner.KeyConfigConfirmVisible){owner.CancelKeySwap();return;}if(!owner.OptionTrainingVisible){owner.ShowTrainingOptions(true);SelectByName("NavTraining");}else owner.SetOptionVisible(false);return;}
  if(confirm){if(selected is Slider||selected is Scrollbar){originalValue=Value();adjusting=true;ShowSelection(selected);}else ExecuteEvents.Execute(selected.gameObject,new BaseEventData(EventSystem.current),ExecuteEvents.submitHandler);return;}
  Vector2 direction=up?Vector2.up:down?Vector2.down:left?Vector2.left:right?Vector2.right:Vector2.zero;if(direction!=Vector2.zero)Move(direction);
 }
 float Value(){if(selected is Slider s)return s.normalizedValue;if(selected is Scrollbar b)return b.value;return 0;}
 void SetValue(float value){if(selected is Slider s)s.normalizedValue=value;else if(selected is Scrollbar b)b.value=value;}
 public void SelectByName(string name){foreach(var item in root.GetComponentsInChildren<Selectable>())if(item.name==name&&Eligible(item)){EventSystem.current.SetSelectedGameObject(item.gameObject);ShowSelection(item);Reveal(item);return;}}
 Vector2 Center(Selectable s){var rect=s.transform as RectTransform;return RectTransformUtility.WorldToScreenPoint(owner.HudCamera,rect.TransformPoint(rect.rect.center));}
 Vector2 ScreenSize(Selectable item){var rect=(RectTransform)item.transform;var corners=new Vector3[4];rect.GetWorldCorners(corners);return RectTransformUtility.WorldToScreenPoint(owner.HudCamera,corners[2])-RectTransformUtility.WorldToScreenPoint(owner.HudCamera,corners[0]);}
 void Move(Vector2 direction){var origin=Center(selected);var size=ScreenSize(selected);Selectable best=null;for(int pass=0;pass<2&&best==null;pass++){float score=-1;foreach(var candidate in root.GetComponentsInChildren<Selectable>()){if(candidate==selected||!Eligible(candidate))continue;var delta=Center(candidate)-origin;float dot=Vector2.Dot(delta,direction);if(dot<=1)continue;var other=ScreenSize(candidate);float perpendicular=Mathf.Abs(direction.x)!=0?Mathf.Abs(delta.y):Mathf.Abs(delta.x);float band=Mathf.Abs(direction.x)!=0?(Mathf.Abs(size.y)+Mathf.Abs(other.y))*.5f:(Mathf.Abs(size.x)+Mathf.Abs(other.x))*.5f;if(pass==0&&perpendicular>band)continue;float next=dot/Mathf.Max(1,delta.sqrMagnitude);if(next>score){best=candidate;score=next;}}}if(best!=null){EventSystem.current.SetSelectedGameObject(best.gameObject);ShowSelection(best);Reveal(best);}}
 void Reveal(Selectable item){var scroll=item.GetComponentInParent<ScrollRect>();if(scroll==null||scroll.content==null||scroll.viewport==null||!item.transform.IsChildOf(scroll.content))return;Canvas.ForceUpdateCanvases();scroll.StopMovement();var b=RectTransformUtility.CalculateRelativeRectTransformBounds(scroll.viewport,item.transform);var r=scroll.viewport.rect;Vector2 offset=Vector2.zero;if(b.min.y<r.yMin)offset.y=r.yMin-b.min.y;if(b.max.y>r.yMax)offset.y=r.yMax-b.max.y;if(b.min.x<r.xMin)offset.x=r.xMin-b.min.x;if(b.max.x>r.xMax)offset.x=r.xMax-b.max.x;scroll.content.anchoredPosition+=offset;}
 void ShowSelection(Selectable next){foreach(var pair in outlines)if(pair.Key!=null&&pair.Value!=null)pair.Value.enabled=false;selected=next;if(next==null)return;if(!outlines.TryGetValue(next,out var outline)||outline==null){var target=next.targetGraphic==null?next.gameObject:next.targetGraphic.gameObject;outline=target.AddComponent<Outline>();outline.effectDistance=new Vector2(3,-3);outlines[next]=outline;}outline.effectColor=Adjusting?new Color(1,.6f,.15f,1):new Color(.3f,1,1,1);outline.enabled=true;}
 void OnDisable(){adjusting=false;foreach(var pair in outlines)if(pair.Value!=null)pair.Value.enabled=false;selected=null;if(ownsNavigation&&EventSystem.current!=null)EventSystem.current.sendNavigationEvents=previousNavigation;ownsNavigation=false;}
}
